// The crag: grey rock heightfield under the whole castle, with terraces.
import { hash } from "./shared.mjs";
const rects = [
  // [x0,z0,x1,z1, top y]
  [38, 5, 72, 14, 10], [20, 8, 90, 30, 10],
  [6, 28, 106, 51, 16],
];
export const LOWER = 10, UPPER = 16;
export function terrainHeight(x, z) {
  let best = -1;
  for (const [x0, z0, x1, z1, top] of rects) {
    const dx = Math.max(x0 - x, 0, x - x1), dz = Math.max(z0 - z, 0, z - z1);
    const d = Math.hypot(dx, dz);
    const n = (hash(x >> 1, z >> 1, 7) - 0.5) * 3 + (hash(x, z, 3) - 0.5) * 1.2;
    const h = d === 0 ? top : top - d * 1.45 - Math.max(0, n) * Math.min(1, d / 3) + (n < 0 ? n * 0.3 : 0);
    best = Math.max(best, h);
  }
  return Math.max(1, Math.round(best));
}
const MIX = ["stone", "stone", "andesite", "stone", "cobblestone", "tuff", "andesite", "mossy_cobblestone", "stone", "gravel"];
export function rock(g) {
  const [W, , D] = g.size;
  for (let x = 0; x < W; x++) for (let z = 0; z < D; z++) {
    const h = terrainHeight(x, z);
    const hx = Math.max(terrainHeight(Math.max(0, x - 1), z), terrainHeight(Math.min(W - 1, x + 1), z));
    const hz = Math.max(terrainHeight(x, Math.max(0, z - 1)), terrainHeight(x, Math.min(D - 1, z + 1)));
    const slope = Math.max(Math.abs(hx - h), Math.abs(hz - h));
    for (let y = 0; y <= h; y++) {
      const top = y >= h - 1;
      let b = "stone";
      if (y === 0) b = "stone";
      else if (top) b = MIX[Math.floor(hash(x, z, y + 11) * MIX.length)];
      else b = hash(x, z, y) < 0.25 ? "andesite" : hash(x, z, y + 5) < 0.12 ? "tuff" : "stone";
      if (top && slope <= 1 && h < 9 && hash(x, z, 99) < 0.35) b = "moss_block";
      g.set(x, y, z, b);
    }
  }
}
