  for (let dx = -r - 1; dx <= r + 1; dx++) for (let dz = -r - 1; dz <= r + 1; dz++) {
    const d = Math.hypot(dx, dz);
    if (d <= r + 1.5 && d > r - 0.3) {
      const f = Math.abs(dx) > Math.abs(dz) ? (dx > 0 ? "west" : "east") : (dz > 0 ? "north" : "south");
      setIfAir(g, cx + dx, y, cz + dz, ...B.stairs(mat, f, "top"));
    }
  }
