/** Arrow slits spiralling up a round tower (cx,cz,r), from y0 every `step`. */
export function spiralSlits(g, cx, cz, r, y0, y1, step = 4, turn = 70) {
  let k = 0;
  for (let y = y0; y <= y1; y += step, k++) {
