export function stepGable(g, { face: f, plane, from, to, y, rise = 2, run = 2, block, coping, crown = 3 }) {
  const w = recorder(g);
  let lo = Math.min(from, to), hi = Math.max(from, to), yy = y;
  const cap = (a) => { if (coping) w.set(...planeXYZ(f, plane, a, yy), ...copingPair(coping.block)); };
  for (;;) {
    for (let r = 0; r < rise; r++, yy++) for (let a = lo; a <= hi; a++) w.set(...planeXYZ(f, plane, a, yy), ...asPair(block));
    const nlo = lo + run, nhi = hi - run;
    if (nhi - nlo + 1 < Math.max(1, crown)) { for (let a = lo; a <= hi; a++) cap(a); break; }
    for (let a = lo; a <= hi; a++) if (a < nlo || a > nhi) cap(a);       // treads
    lo = nlo; hi = nhi;
  }
  return w.done();
}

