export function boulder(g, centre, size, { materials = ["stone", "andesite", "stone", "cobblestone"], moss = 0.35, flatTop = false, amount = 0.3, seed = 3 } = {}) {
  const [rx, ry, rz] = Array.isArray(size) ? size : [size, size * 0.75, size];
  const [cx, cy, cz] = centre;
  const inside = (x, y, z) => {
    const dx = (x - cx) / rx, dy = (y - cy) / ry, dz = (z - cz) / rz;
    if (flatTop && y > cy + ry * 0.4) return false;
    return dx * dx + dy * dy + dz * dz <= 1 + amount * (fbm(x / 2.5, y / 2.5, z / 2.5, seed) - 0.5) * 2.4;
  };
  let cells = 0;
  for (let x = Math.floor(cx - rx - 1); x <= Math.ceil(cx + rx + 1); x++) for (let y = Math.floor(cy - ry - 1); y <= Math.ceil(cy + ry + 1); y++) for (let z = Math.floor(cz - rz - 1); z <= Math.ceil(cz + rz + 1); z++) {
    if (!inB(g, x, y, z) || !inside(x, y, z)) continue;
    const top = !inside(x, y + 1, z);
    let b = pick(materials, noise3(x / 3, y / 2, z / 3, seed + 9));
    if (top && hash3(x, y, z, seed) < moss) b = noise2(x / 2, z / 2, seed) < 0.5 ? "moss_block" : "mossy_cobblestone";
    g.set(x, y, z, b); cells++;
  }
  return { cells };
}
